sql.if:
JOIN sys_organization_user sou_perm ON CONVERT(c.owner USING utf8mb4) COLLATE utf8mb4_general_ci =
    CONVERT(sou_perm.user_id USING utf8mb4) COLLATE utf8mb4_general_ci
 AND sou_perm.organization_id = #{orgId}
 AND (
    sou_perm.department_id IN

        #{deptId}


        OR sou_perm.user_id = #{userId}

 )

JOIN customer_collaboration cc_perm ON CONVERT(c.id USING utf8mb4) COLLATE utf8mb4_general_ci =
    CONVERT(cc_perm.customer_id USING utf8mb4) COLLATE utf8mb4_general_ci
 AND cc_perm.user_id = #{userId}

mapper.select:
SELECT DISTINCT su.name
FROM sys_user su
JOIN sys_organization_user sou
  ON sou.user_id = su.id
 AND sou.organization_id = #{orgId}
WHERE su.name IS NOT NULL
  AND su.name != ''




        AND sou.user_id = #{userId}


        AND (
            sou.department_id IN

                #{deptId}


                OR sou.user_id = #{userId}

        )


        AND 1 = 0

SELECT c.id, c.name, c.owner, u.name AS ownerName, c.email, c.wecom_external_id AS wecomExternalId, c.roomid, c.full_name AS fullName, c.region, c.phone, c.address, c.remark, c.follow_time AS followTime, c.create_time AS createTime, c.update_time AS updateTime FROM customer c LEFT JOIN sys_user u ON CONVERT(c.owner USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(u.id USING utf8mb4) COLLATE utf8mb4_general_ci
WHERE
AND u.name LIKE CONCAT('%', #{specialistName}, '%')
AND c.owner = #{userId}
ORDER BY COALESCE(c.follow_time, c.update_time, c.create_time) DESC LIMIT #{limit}

SELECT FROM customer c LEFT JOIN sys_user u ON CONVERT(c.owner USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(u.id USING utf8mb4) COLLATE utf8mb4_general_ci
WHERE
AND u.name LIKE CONCAT('%', #{specialistName}, '%')
AND c.owner = #{userId}
GROUP BY c.id, c.name, c.owner, u.name HAVING wecomMessageCount > 0 OR emailCount > 0 OR followRecordCount > 0 ORDER BY lastCommunicationTime DESC LIMIT #{limit}

SELECT FROM customer c LEFT JOIN sys_user u ON CONVERT(c.owner USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(u.id USING utf8mb4) COLLATE utf8mb4_general_ci
WHERE
GROUP BY c.id, c.name, c.owner, u.name ORDER BY lastCommunicationTime DESC LIMIT #{limit}

SELECT fr.id, fr.customer_id AS customerId, c.name AS customerName, fr.owner AS ownerId, u.name AS ownerName, fr.follow_method AS followMethod, fr.content, fr.follow_time AS followTime FROM follow_up_record fr JOIN customer c ON CONVERT(fr.customer_id USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(c.id USING utf8mb4) COLLATE utf8mb4_general_ci AND c.organization_id = #{orgId} LEFT JOIN sys_user u ON CONVERT(fr.owner USING utf8mb4) COLLATE utf8mb4_general_ci = CONVERT(u.id USING utf8mb4) COLLATE utf8mb4_general_ci
WHERE fr.organization_id = #{orgId}
AND ( c.name LIKE CONCAT('%', #{customerName}, '%') OR c.full_name LIKE CONCAT('%', #{customerName}, '%') )
ORDER BY fr.follow_time DESC LIMIT #{limit}

SELECT id,
       title,
       '客户经营智能体' AS agentName,
       update_time AS updateTime
FROM ai_agent_session
WHERE organization_id = #{orgId}
  AND user_id = #{userId}
ORDER BY update_time DESC
LIMIT #{limit}

mapper.delete:
DELETE l
FROM ai_agent_tool_call_log l
JOIN ai_agent_message m ON m.id = l.message_id
JOIN ai_agent_session s ON s.id = m.session_id
WHERE s.id = #{sessionId}
  AND s.organization_id = #{orgId}
  AND s.user_id = #{userId}

DELETE f
FROM ai_agent_feedback f
JOIN ai_agent_message m ON m.id = f.message_id
JOIN ai_agent_session s ON s.id = m.session_id
WHERE s.id = #{sessionId}
  AND s.organization_id = #{orgId}
  AND s.user_id = #{userId}

DELETE m
FROM ai_agent_message m
JOIN ai_agent_session s ON s.id = m.session_id
WHERE s.id = #{sessionId}
  AND s.organization_id = #{orgId}
  AND s.user_id = #{userId}

DELETE FROM ai_agent_session
WHERE id = #{sessionId}
  AND organization_id = #{orgId}
  AND user_id = #{userId}
